   C("«店» ханзын гаднах хэсэг аль нь вэ?",["广","巾","王"],0,"Зөв. 广 + 占 = 店.","巾 нь 帽, 帮, 带-д."),
   J("«麻» ханзад «广» хэсэг байна уу?",True,"Зөв. 广 + 林 = 麻.","Буруу. 麻 = 广 + 林."),
